def rebuild(preorder: list[int], inorder: list[int]) -> "TreeNode | None":
    where = {val: i for i, val in enumerate(inorder)}
    roots = iter(preorder)                # preorder hands out each subtree's root in turn

    def build(lo: int, hi: int) -> "TreeNode | None":
        """The subtree whose inorder walk is inorder[lo:hi]."""
        if lo == hi:
            return None
        node = TreeNode(next(roots))
        mid = where[node.val]
        node.left = build(lo, mid)        # the whole left subtree comes next in preorder
        node.right = build(mid + 1, hi)
        return node

    return build(0, len(inorder))


